function StoreDiamondExchangeDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self.valueCusOIL = argument.overrideSorting
        self._userId = checkNumber(argument.id)
        if self._userId == 0 then
            return
        end 
        local vo =  CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", self._userId)
        if not vo then
            return
        end
        self._vo = vo

        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function StoreDiamondExchangeDialog:InitData()
    local num = GoodsUtils.GetThingNo(self._vo.itemId)           --兑换最大次数
    
    self._maxChangeNum = math.floor(num / checkNumber(self._vo.itemIdCost))
    if self._maxChangeNum == 0 then
        self._maxChangeNum = 1
    end

    if checkNumber(self._vo.getItemId) == ActionUtils.GetDailyQuestTicketId() then
        self._maxHaveNum = ActionUtils.GetDailyQuestMaxTicketNum()
    end
end

function StoreDiamondExchangeDialog:FillSelf()
    self:FillConsumeInfo()
    self:FillGetInfo()

    self:FillChangeNum()
end

function StoreDiamondExchangeDialog:OnChange()
    --又最大持有数
    if self._maxHaveNum > 0 then
        local curHave = 0
        if checkNumber(self._vo.getItemId) == ActionUtils.GetDailyQuestTicketId() then
            curHave = ActionUtils.GetDailyQuestCurTicketAddNum()
        end
        if curHave >= self._maxHaveNum then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.getItemId)
            GameUtils.Toast(localize("_name_已达到最大数量", {_name_ = vo.name}))
            return
        end
    end

    local num = GoodsUtils.GetThingNo(self._vo.itemId)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.itemId)
    if num == 0 then
        UIModule.CloseDialog(self.controller)
        GoodsUtils.ShowCommonLackMaterialDialog({{goodsId = self._vo.itemId, num = 1 }})
        --GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
        return
    end

    local t = {
        goodsId = self._vo.itemId,
        num = checkNumber(self._curChangeNum),
    }
    GameUtils.Request(Interfaces.PlayerStrengthHP, { consume = table.serialize(t)}, function(request, responseTable)
        if checkNumber(responseTable.errCode) ~= 0 then
            return
        end
        local jsonData = responseTable.data

        GoodsUtils.DrawRewards({[1] = {goodsId = t.goodsId, num = -t.num * checkNumber(self._vo.itemIdCost)}})
        if checkNumber(self._vo.getItemId) == ActionUtils.GetDailyQuestTicketId() then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
            comp:AddTicketCount(checkNumber(self._vo.getItemCost) * t.num)
            Events.Broadcast(Constants.EventNames.EveryThingChangeEventName)
        else
            GoodsUtils.DrawRewards(jsonData.rewards, true)
        end

        UIModule.CloseDialog(self.controller)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })
        
        local callback = self.controller.Argument.parameters.callback
        if not isNull(callback) then
            callback()
        end
    end)
end

function StoreDiamondExchangeDialog:OnBtnAdd()
    if self._curChangeNum >= self._maxChangeNum then
        return
    end
    self._curChangeNum = self._curChangeNum + 1
    self:FillChangeNum()
end

function StoreDiamondExchangeDialog:OnBtnDel()
    if self._curChangeNum <= 1 then
        return
    end
    self._curChangeNum = self._curChangeNum - 1
    self:FillChangeNum()
end

function StoreDiamondExchangeDialog:OnBtnTenDel()
    self._curChangeNum = self._curChangeNum - 10
    if self._curChangeNum <= 1 then
        self._curChangeNum = 1
    end
    self:FillChangeNum()
end

function StoreDiamondExchangeDialog:OnBtnTenAdd()
    self._curChangeNum = self._curChangeNum + 10
    if self._curChangeNum >= self._maxChangeNum then
        self._curChangeNum = self._maxChangeNum
    end
    self:FillChangeNum()
end

function StoreDiamondExchangeDialog:FillChangeNum()
    self.InputFieldNumber.text = self._curChangeNum
    CfUtils.FillCommonBtnConsumePopNode(self.controller.gameObject.transform:Find("Container/Root/Details/CommonBtnConsumePop"), self._vo.itemId, self._curChangeNum, true)
end

function StoreDiamondExchangeDialog:FillConsumeInfo()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.itemId)
    CfUtils.FillImage(self.ConsumeImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._vo.itemId))
    CfUtils.FillText(self.ConsumeTxtNumber, self._vo.itemIdCost)
    CfUtils.FillText(self.ConsumeTxtName, vo.name)
    CfUtils.SetUISwitchImage(self.ConsumeImgFrame, vo.quality)
end

function StoreDiamondExchangeDialog:FillGetInfo()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.getItemId)
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._vo.getItemId))
    CfUtils.FillText(self.TxtNumber, self._vo.getItemCost)
    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.SetUISwitchImage(self.ImgFrame, vo.quality)

    CfUtils.FillText(self.TxtInstructions, localize("兑换_name_数量", {_name_ = vo.name}))
    local scr = CfUtils.GetLuaScr(self.CommonUITitleNode, TitleNodeScrPath)
    if scr then
        scr:Refresh(localize("兑换_name_", {_name_ = vo.name}))
    end
end

